const platformName = "ats";

for (const item of $input.all()) {
  item.json.source = platformName;
}

return $input.all();

const today = new Date().getDay();
let publishedAtString = "1 day"; 

if (today === 1) { 
  publishedAtString = "3 days"; 
}

return {
  publishedAtString
};

const inputPrevious = $input.item.json;

const keywords = [
  "AI engineer",
  //"AI solutions",
  "AI Agent",
  "AI consultant",
  //"n8n",
  "MLOps",
  //"Automation engineer"
];

return {
  ...inputPrevious,
  keywords 
};

parameters.query:
UPDATE public.workflow_health 
SET loop_count = loop_count + 1 
WHERE workflow_tag = '{{ $json.source }}';

